// Some portions generated by Co-Pilot
import React from "react";
import { render, screen, fireEvent, cleanup } from "@testing-library/react";
import { describe, it, vi, expect, afterEach, beforeEach } from "vitest";
import BecomeAdopter from "../index";
import { axe } from "vitest-axe";

const params = vi.hoisted(() => ({ open: null as string | null }));

// ✅ robust mock
vi.mock("next/navigation", async () => ({
  useSearchParams: () => ({
    get: () => params.open,
  }),
}));

describe("BecomeAdopter", () => {
  beforeEach(() => {
    params.open = null;
    vi.spyOn(window, "requestAnimationFrame").mockReturnValue(1);
  });
  afterEach(() => {
    cleanup();
    vi.restoreAllMocks();
  });

  it("renders the button", () => {
    render(<BecomeAdopter />);
    expect(
      screen.getByRole("button", {
        name: /how can i get my logo displayed/i,
      }),
    ).toBeInTheDocument();
  });

  it("shows dropdown content when button is clicked", () => {
    render(<BecomeAdopter />);
    const button = screen.getByRole("button", {
      name: /how can i get my logo displayed/i,
    });

    fireEvent.click(button);

    expect(screen.getByText(/option 1 - open an issue/i)).toBeInTheDocument();

    expect(
      screen.getByText(/option 2 - submit a pull request/i),
    ).toBeInTheDocument();
  });

  it("hides dropdown content when button is clicked twice", () => {
    render(<BecomeAdopter />);
    const button = screen.getByRole("button", {
      name: /how can i get my logo displayed/i,
    });

    fireEvent.click(button);
    fireEvent.click(button);

    expect(
      screen.queryByText(/option 1 - open an issue/i),
    ).not.toBeInTheDocument();
  });

  it("opens from shared URLs and follows changes to the open parameter", () => {
    params.open = "adopter";
    const { rerender } = render(<BecomeAdopter />);
    expect(
      screen.getByRole("heading", { name: "Option 1 - Open an Issue" }),
    ).toBeVisible();
    expect(window.requestAnimationFrame).toHaveBeenCalled();
    const button = screen.getByRole("button", {
      name: "How can I get my logo displayed?",
    });
    expect(button).toHaveAttribute("aria-expanded", "true");
    fireEvent.click(button);
    expect(button).toHaveAttribute("aria-expanded", "false");
    params.open = null;
    rerender(<BecomeAdopter />);
    params.open = "adopter";
    rerender(<BecomeAdopter />);
    expect(button).toHaveAttribute("aria-expanded", "true");
  });

  it("keeps controls and submission links accessible in both states", async () => {
    const { container } = render(<BecomeAdopter />);
    const button = screen.getByRole("button");
    expect(
      document.getElementById(button.getAttribute("aria-controls")!),
    ).toHaveAttribute("hidden");
    expect(await axe(container)).toHaveNoViolations();
    fireEvent.click(button);
    for (const link of screen.getAllByRole("link"))
      expect(link).toHaveAttribute("rel", "noopener noreferrer");
    expect(await axe(container)).toHaveNoViolations();
  });
});
